"""Task-list projections shared by paging, filters and counters."""

MANUAL_BASE = "SELECT id, task_code, preview_code, task_name, publish_date, planned_account_count, result_count, failure_count, topic_count, status, failure_reason, t.batch_id, COALESCE((SELECT p.content_mode FROM godp_manual_preview p WHERE p.preview_code=t.preview_code LIMIT 1),'legacy') AS content_mode, CASE WHEN status IN ('执行中','进行中') THEN '待生产' WHEN status <> '已完成' THEN '待生产' WHEN t.batch_id IS NULL OR COALESCE(cs.slot_count, 0)=0 THEN '待生产' WHEN cs.failed_count > 0 THEN '生成失败' WHEN cs.completed_count=cs.slot_count THEN '已完成' WHEN cs.ready_count > 0 OR cs.completed_count > 0 THEN '生成中' ELSE '待生产' END AS content_status, COALESCE(cs.failed_count, 0) AS content_failed_count, COALESCE(cs.completed_count, 0) AS content_completed_count, COALESCE(cs.slot_count, 0) AS content_total_count, COALESCE(cs.completed_account_count, 0) AS content_completed_account_count, COALESCE((SELECT batch_code FROM godp_planning_batch WHERE id=t.batch_id AND del_flag='N'), '') AS batch_code, last_error, create_time AS created_at, create_by AS created_by, update_time AS updated_at FROM godp_manual_task t LEFT JOIN (SELECT i.batch_id, COUNT(*) AS slot_count, COUNT(DISTINCT i.account_id) - COUNT(DISTINCT CASE WHEN COALESCE(NULLIF(s.production_status, ''), CASE WHEN i.status='已发布' THEN 'published' WHEN i.status IN ('已生成','生成完成','生产完成') THEN 'generated' WHEN i.status IN ('生成失败','生产失败','生产异常') THEN 'failed' WHEN i.status IN ('生成中','生产中') THEN 'ready' ELSE 'planned' END) NOT IN ('generated','published') OR NULLIF(i.topic_id, '') IS NULL THEN i.account_id END) AS completed_account_count, SUM(CASE WHEN COALESCE(NULLIF(s.production_status, ''), CASE WHEN i.status='已发布' THEN 'published' WHEN i.status IN ('已生成','生成完成','生产完成') THEN 'generated' WHEN i.status IN ('生成失败','生产失败','生产异常') THEN 'failed' WHEN i.status IN ('生成中','生产中') THEN 'ready' ELSE 'planned' END) IN ('generated','published') THEN 1 ELSE 0 END) AS completed_count, SUM(CASE WHEN COALESCE(NULLIF(s.production_status, ''), CASE WHEN i.status='已发布' THEN 'published' WHEN i.status IN ('已生成','生成完成','生产完成') THEN 'generated' WHEN i.status IN ('生成失败','生产失败','生产异常') THEN 'failed' WHEN i.status IN ('生成中','生产中') THEN 'ready' ELSE 'planned' END)='ready' THEN 1 ELSE 0 END) AS ready_count, SUM(CASE WHEN COALESCE(NULLIF(s.production_status, ''), CASE WHEN i.status='已发布' THEN 'published' WHEN i.status IN ('已生成','生成完成','生产完成') THEN 'generated' WHEN i.status IN ('生成失败','生产失败','生产异常') THEN 'failed' WHEN i.status IN ('生成中','生产中') THEN 'ready' ELSE 'planned' END)='failed' THEN 1 ELSE 0 END) AS failed_count FROM godp_planning_item i LEFT JOIN godp_slot_state s ON s.item_id=i.id AND s.del_flag='N' WHERE i.del_flag='N' GROUP BY i.batch_id) cs ON cs.batch_id=t.batch_id WHERE t.del_flag='N' "
